test('createInvoice: rejects invalid terms (lowercase)', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'PHOTO-LIC', qty: 1 }],
    terms: 'net30',
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'TERMS_INVALID');
});

test('createInvoice: preserves other invoice properties with terms', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'PHOTO-LIC', qty: 2 }],
    terms: 'NET14',
  });
  assert.equal(result.ok, true);
  assert.equal(result.value.customerId, 'C-001');
  assert.equal(result.value.issueDate, '2026-10-07');
  assert.equal(result.value.status, 'draft');
  assert.equal(result.value.lines.length, 1);
});

test('createInvoice: does not mutate input with terms', () => {
  const input = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'PHOTO-LIC', qty: 1 }],
    terms: 'NET30',
  };
  const inputCopy = JSON.stringify(input);
  createInvoice(input);
  assert.equal(JSON.stringify(input), inputCopy);
});

test('createInvoice: dueDate is a valid date', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'PHOTO-LIC', qty: 1 }],
    terms: 'NET30',
  });
  assert.equal(result.ok, true);
  assert.match(result.value.dueDate, /^\d{4}-\d{2}-\d{2}$/);
});

test('createInvoice: terms validation happens after date validation', () => {
  const result = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-13-01',
    lines: [{ sku: 'PHOTO-LIC', qty: 1 }],
    terms: 'NET45',
  });
  assert.equal(result.ok, false);
  assert.equal(result.error, 'DATE_INVALID');
});
